  `full_name` varchar(145) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `email` varchar(145) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `username` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `is_active` tinyint DEFAULT NULL,
  `is_current` tinyint DEFAULT NULL,
  `academy_id` int DEFAULT NULL,
  `created` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `emp_no` int DEFAULT NULL,
  `emp_name_ar` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `emp_name_en` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `emp_job_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `prefix` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `attach_ref_no` bigint DEFAULT NULL,
  `degree_type_id` int DEFAULT NULL,
  `staff_type` tinyint DEFAULT NULL,
  `staff_entity_id` int DEFAULT NULL,
  `address` varchar(145) DEFAULT NULL,
  `phone_number` varchar(45) DEFAULT NULL,
  `iban` varchar(45) DEFAULT NULL,
  `job_title_id` int DEFAULT NULL,
  `status_type` tinyint DEFAULT NULL,
  `military_no` varchar(255) DEFAULT NULL,
  `national_id` varchar(45) DEFAULT NULL,
  `ordered` int DEFAULT NULL,
  `visiting_teacher_classification_id` tinyint DEFAULT NULL,
  `department_settings_id` int DEFAULT NULL,
  `general_seniority` varchar(255) DEFAULT NULL,
  `passport_number` varchar(255) DEFAULT NULL,
  `mandate_entity` varchar(255) DEFAULT NULL,
  `step_status` varchar(255) DEFAULT NULL,
  `bcase_trn_id` decimal(16,0) DEFAULT NULL,
  `bcase_trn_relative_id` decimal(16,0) DEFAULT NULL,
  `draft_id` decimal(16,0) DEFAULT NULL,
  `approved_flag` smallint DEFAULT '0',
  `birth_date` varchar(10) DEFAULT NULL,
  `mandate_entity_attach_ref_no` bigint DEFAULT NULL,
  `iban_attach_ref_no` bigint DEFAULT NULL,
  `military_no_attach_ref_no` bigint DEFAULT NULL,
  `national_id_attach_ref_no` bigint DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `staff_uidx` (`code`) USING BTREE,
  KEY `fk_staff_entity_id_idx` (`staff_entity_id`),
  KEY `fk_degree_type_id_idx` (`degree_type_id`),
  KEY `fk_staff_job_title_id_idx` (`job_title_id`),
  KEY `fk_staff_department_settings_id_idx` (`department_settings_id`),
